class Solution {
  public long[] countKConstraintSubstrings(String s, int k, int[][] queries) {
    int n = s.length(), zeros = 0, ones = 0, start = 0;
    int[] first = new int[n]; // smallest start such that s[first..i] satisfies the constraint
    long[] prefix =
        new long[n + 1]; // prefix[i + 1]: valid substrings ending at 0..i (from first[i])
    for (int i = 0; i < n; i++) {
      if (s.charAt(i) == '0') zeros++;
      else ones++;
      while (zeros > k && ones > k) {
        if (s.charAt(start++) == '0') zeros--;
        else ones--;
      }
      first[i] = start;
      prefix[i + 1] = prefix[i] + (i - start + 1);
    }
    long[] answer = new long[queries.length];
    for (int q = 0; q < queries.length; q++) {
      int l = queries[q][0], r = queries[q][1];
      // first[] is non-decreasing: find the first end p whose window already starts at or after l
      int lo = l, hi = r + 1;
      while (lo < hi) {
        int mid = (lo + hi) >>> 1;
        if (first[mid] >= l) hi = mid;
        else lo = mid + 1;
      }
      long head = lo - l; // ends l..lo-1 are limited by l itself: every start in [l, end] is valid
      answer[q] = head * (head + 1) / 2 + prefix[r + 1] - prefix[lo];
    }
    return answer;
  }
}
